def solve(n, edges):
    def bfs(start):
        queue = [start]
        visited = set()
        visited.add(start)
        while queue:
            node = queue.pop(0)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return visited

    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited_nodes = set()
    components = 0

    for node in range(n):
        if node not in visited_nodes:
            component = bfs(node)
            visited_nodes.update(component)
            components += 1

    return components
