def solve(n, edges):
    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_v] = root_u

    for u, v in edges:
        union(u, v)

    root_count = set()
    for i in range(n):
        root_count.add(find(i))

    return len(root_count)
