def solve(n, edges):
    def get_parent(parent, u):
        if parent[u] != u:
            parent[u] = get_parent(parent, parent[u])
        return parent[u]

    def union(parent, rank, u, v):
        u_root = get_parent(parent, u)
        v_root = get_parent(parent, v)
        if u_root == v_root:
            return
        if rank[u_root] < rank[v_root]:
            parent[u_root] = v_root
        else:
            parent[v_root] = u_root
            if rank[u_root] == rank[v_root]:
                rank[u_root] += 1

    parent = list(range(n))
    rank = [1] * n

    for u, v in edges:
        union(parent, rank, u, v)

    components = set()
    for i in range(n):
        components.add(get_parent(parent, i))

    return len(components)
